const row = $json;
const highItems = Array.isArray(row.high_items) ? row.high_items : [];
const digestDate = new Date(Date.now() + 9 * 60 * 60 * 1000).toISOString().slice(0, 10);
const dateDigits = digestDate.replaceAll('-', '');
const retryKey = `${dateDigits}-0000-4000-8000-000000000000`;
const lines = [
  'AIメールアシスタント 日次ダイジェスト',
  `処理件数: ${row.total_count ?? 0}`,
  `重要: ${row.high_count ?? 0} / 通常: ${row.normal_count ?? 0}`,
  `予定登録: ${row.calendar_created_count ?? 0}`,
  `簡易エラー: ${row.error_count ?? 0}`,
];
if (highItems.length) {
  lines.push('', '重要メール');
  for (const item of highItems.slice(0, 10)) {
    const subject = String(item.subject ?? '(件名なし)').replace(/[\r\n]+/g, ' ').slice(0, 80);
    const summary = String(item.summary ?? '').replace(/[\r\n]+/g, ' ').slice(0, 160);
    lines.push(`- ${subject}${summary ? `: ${summary}` : ''}`);
  }
}
return [{ json: { ...row, digestDate, digestText: lines.join('\n'), retryKey } }];

const status = Number($json.statusCode ?? $json.httpCode ?? $json.error?.statusCode);
if (status === 409) return [{ json: { accepted: true, duplicate: true } }];
throw new Error(`LINE digest delivery failed (status: ${Number.isFinite(status) ? status : 'unknown'})`);
